def compute(vars):
    shares_millions = vars["v1"]
    price_per_share = vars["v2"]
    total_cash_inflow = shares_millions * price_per_share
    return {
        "value": total_cash_inflow,
        "trace": {
            "shares_millions": shares_millions,
            "price_per_share": price_per_share,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
